//! Local sitemap ZIP packages with bounded index/parts and observed optional hints.
use crate::{Page,Result};
use serde::{Serialize,Deserialize};
use std::{collections::{BTreeMap,BTreeSet},io::Write,path::{Path,PathBuf}};
use url::Url;
const HEADER:&str="<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<urlset xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n";
const FOOTER:&str="</urlset>\n";
const MAX_BYTES:usize=50*1024*1024;
#[derive(Debug,Clone,Serialize,Deserialize)]#[serde(default)]pub struct Options{pub public_base:String,pub max_urls:usize,pub max_bytes:usize,pub gzip:bool,pub readable_unicode:bool,pub lastmod:bool,pub changefreq:Option<String>,pub priority:Option<f64>}
impl Default for Options{fn default()->Self{Self{public_base:String::new(),max_urls:50000,max_bytes:MAX_BYTES,gzip:false,readable_unicode:true,lastmod:false,changefreq:None,priority:None}}}
#[derive(Debug,Serialize)]pub struct Part{pub name:String,pub urls:usize,pub uncompressed_bytes:usize}
#[derive(Debug,Serialize)]pub struct Summary{pub origin:String,pub public_base:String,pub eligible_urls:usize,pub skipped_urls:usize,pub skipped_reasons:BTreeMap<String,usize>,pub parts:Vec<Part>,pub index_file:String,pub index_bytes:usize,pub gzip:bool,pub readable_unicode:bool,pub lastmod_omitted:usize,pub outside_public_directory:usize}
#[derive(Debug,Serialize)]pub struct Excluded{pub url:String,pub reason:String}
#[derive(Debug,Serialize)]pub struct Report{pub summary:Summary,pub excluded:Vec<Excluded>}
fn escape(value:&str)->String{crate::escape(value).replace('\'',"&apos;")}
fn location(value:&str,readable:bool)->String{if readable{crate::display_url(value)}else{value.into()}}
fn public_directory(seed:&Url,options:&Options)->Result<Url>{
 if !(1..=50000).contains(&options.max_urls)||!(1024..=MAX_BYTES).contains(&options.max_bytes){return Err("Sitemap parts require 1–50000 URLs and 1024–52428800 uncompressed bytes".into())}
 if options.priority.is_some_and(|value|!value.is_finite()||!(0.0..=1.0).contains(&value)){return Err("Priority must be between 0.0 and 1.0".into())}
 if options.changefreq.as_ref().is_some_and(|value|!["always","hourly","daily","weekly","monthly","yearly","never"].contains(&value.as_str())){return Err("Choose a supported sitemap change frequency or omit the hint".into())}
 let mut base=Url::parse(options.public_base.trim())?;if !matches!(base.scheme(),"http"|"https")||base.host_str().is_none()||base.origin()!=seed.origin()||!base.username().is_empty()||base.password().is_some()||base.query().is_some()||base.fragment().is_some(){return Err("Public sitemap directory must use the crawl seed origin, with no credentials, query or fragment".into())}
 if !base.path().ends_with('/'){base.set_path(&format!("{}/",base.path()));}if location(base.as_str(),options.readable_unicode).chars().count()+32>=2048{return Err("Public sitemap directory is too long for sitemap index locations".into())}Ok(base)
}
fn reason(page:&Page,origin:&url::Origin,seen:&mut BTreeSet<String>,readable:bool)->Option<&'static str>{
 let parsed=match Url::parse(&page.url){Ok(url)=>url,Err(_)=>return Some("Invalid URL")};if !matches!(parsed.scheme(),"http"|"https")||parsed.host_str().is_none()||!parsed.username().is_empty()||parsed.password().is_some()||page.url.chars().any(char::is_control){return Some("Invalid URL")}
 if !page.internal||&parsed.origin()!=origin{return Some("External URL")}
 if !(200..300).contains(&page.status){return Some("Non-success response")}
 if !page.content_type.to_ascii_lowercase().contains("html"){return Some("Non-HTML response")}
 if page.html_extracted==Some(false){return Some("HTML extraction unavailable")}
 if crate::directives::restriction(page,"googlebot","noindex"){return Some("Noindex directive")}
 if !page.canonical.is_empty()&&page.canonical!=page.url{return Some("Canonical points elsewhere")}
 if parsed.fragment().is_some(){return Some("Fragment URL")}
 if location(&page.url,readable).chars().count()>=2048{return Some("Location exceeds 2047 characters")}
 if !seen.insert(page.url.clone()){return Some("Duplicate URL")}
 None
}
fn comparable_path(url:&Url)->String{static HEX:std::sync::OnceLock<regex::Regex>=std::sync::OnceLock::new();HEX.get_or_init(||regex::Regex::new(r"%[0-9a-fA-F]{2}").unwrap()).replace_all(url.path(),|value:&regex::Captures<'_>|value[0].to_ascii_uppercase()).into_owned()}
fn observed_lastmod(page:&Page)->Option<String>{let raw=page.headers.get("last-modified")?;let date=httpdate::parse_http_date(raw).ok()?;time::OffsetDateTime::from(date).format(&time::format_description::well_known::Rfc3339).ok()}
fn entry(page:&Page,options:&Options)->(String,bool){let mut xml=format!("  <url><loc>{}</loc>",escape(&location(&page.url,options.readable_unicode)));let mut missing=false;
 if options.lastmod{match observed_lastmod(page){Some(date)=>xml.push_str(&format!("<lastmod>{date}</lastmod>")),None=>missing=true}}
 if let Some(value)=&options.changefreq{xml.push_str(&format!("<changefreq>{value}</changefreq>"))}if let Some(value)=options.priority{xml.push_str(&format!("<priority>{value}</priority>"))}xml.push_str("</url>\n");(xml,missing)
}
struct Temporary(PathBuf);impl Drop for Temporary{fn drop(&mut self){let _=std::fs::remove_file(&self.0);}}
static TEMPORARY_COUNTER:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(0);
fn own_temporary(path:PathBuf)->Result<(std::fs::File,Temporary)>{let file=std::fs::OpenOptions::new().write(true).create_new(true).open(&path)?;Ok((file,Temporary(path)))}
fn write_part(writer:&mut zip::ZipWriter<std::fs::File>,parts:&mut Vec<Part>,mut xml:String,count:usize,options:&Options)->Result<()>{
 if parts.len()>=50000{return Err("Sitemap index exceeds 50000 child files; use fewer parts".into())}xml.push_str(FOOTER);let bytes=xml.len();if bytes>options.max_bytes{return Err("Uncompressed sitemap part exceeds configured byte limit".into())}
 let name=format!("sitemap-{:05}.xml{}",parts.len()+1,if options.gzip{".gz"}else{""});let method=if options.gzip{zip::CompressionMethod::Stored}else{zip::CompressionMethod::Deflated};writer.start_file(&name,zip::write::SimpleFileOptions::default().compression_method(method))?;
 if options.gzip{let mut encoder=flate2::write::GzEncoder::new(Vec::new(),flate2::Compression::default());encoder.write_all(xml.as_bytes())?;writer.write_all(&encoder.finish()?)?;}else{writer.write_all(xml.as_bytes())?;}
 parts.push(Part{name,urls:count,uncompressed_bytes:bytes});Ok(())
}
pub fn export_pages(pages:&[Page],seed:&str,path:&str,options:Options)->Result<Report>{crate::export_target::check(path)?;
 if !Path::new(path).extension().and_then(|value|value.to_str()).is_some_and(|value|value.eq_ignore_ascii_case("zip")){return Err("Choose a .zip file for the sitemap package".into())}
 let seed=Url::parse(seed)?;let base=public_directory(&seed,&options)?;let mut accepted=Vec::new();let mut excluded=Vec::new();let mut skipped_reasons=BTreeMap::new();let mut seen=BTreeSet::new();
 for page in pages{if let Some(reason)=reason(page,&seed.origin(),&mut seen,options.readable_unicode){*skipped_reasons.entry(reason.to_string()).or_insert(0)+=1;excluded.push(Excluded{url:page.url.clone(),reason:reason.into()})}else{accepted.push(page)}}
 if accepted.is_empty(){return Err("No successful indexable HTML URLs are eligible for this sitemap package".into())}if accepted.len().div_ceil(options.max_urls)>50000{return Err("Requested URL split would exceed 50000 sitemap files".into())}
 let public_path=comparable_path(&base);let outside_public_directory=if public_path=="/"{0}else{accepted.iter().filter(|page|Url::parse(&page.url).map(|url|!comparable_path(&url).starts_with(&public_path)).unwrap_or(false)).count()};let output=Path::new(path);let parent=output.parent().filter(|parent|!parent.as_os_str().is_empty()).unwrap_or_else(||Path::new("."));std::fs::create_dir_all(parent)?;
 let nonce=std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_nanos();let sequence=TEMPORARY_COUNTER.fetch_add(1,std::sync::atomic::Ordering::SeqCst);let(file,temporary)=own_temporary(parent.join(format!(".fitig-sitemap-{}-{nonce}-{sequence}.tmp",std::process::id())))?;let mut writer=zip::ZipWriter::new(file);let mut parts=Vec::new();let mut xml=HEADER.to_string();let mut count=0;let mut lastmod_omitted=0;
 for page in &accepted{let(line,missing)=entry(page,&options);if HEADER.len()+line.len()+FOOTER.len()>options.max_bytes{return Err("One URL entry exceeds the chosen XML byte limit; increase the file-size limit".into())}if count>=options.max_urls||xml.len()+line.len()+FOOTER.len()>options.max_bytes{write_part(&mut writer,&mut parts,xml,count,&options)?;xml=HEADER.to_string();count=0}xml.push_str(&line);count+=1;lastmod_omitted+=usize::from(missing);}
 if count>0{write_part(&mut writer,&mut parts,xml,count,&options)?;}
 let mut index=String::from("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<sitemapindex xmlns=\"http://www.sitemaps.org/schemas/sitemap/0.9\">\n");let index_footer="</sitemapindex>\n";
 for part in &parts{let url=base.join(&part.name)?;let line=format!("  <sitemap><loc>{}</loc></sitemap>\n",escape(&location(url.as_str(),options.readable_unicode)));if index.len()+line.len()+index_footer.len()>MAX_BYTES{return Err("Sitemap index exceeds the 50 MiB uncompressed limit".into())}index.push_str(&line)}index.push_str(index_footer);
 let summary=Summary{origin:seed.origin().ascii_serialization(),public_base:location(base.as_str(),options.readable_unicode),eligible_urls:accepted.len(),skipped_urls:excluded.len(),skipped_reasons,parts,index_file:"sitemap-index.xml".into(),index_bytes:index.len(),gzip:options.gzip,readable_unicode:options.readable_unicode,lastmod_omitted,outside_public_directory};
 writer.start_file("sitemap-index.xml",zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated))?;writer.write_all(index.as_bytes())?;writer.start_file("manifest.json",zip::write::SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated))?;writer.write_all(&serde_json::to_vec_pretty(&summary)?)?;let file=writer.finish()?;file.sync_all()?;drop(file);std::fs::rename(&temporary.0,output)?;Ok(Report{summary,excluded})
}
pub fn export(db:&str,path:&str,options:Options)->Result<Report>{if Path::new(db).canonicalize().ok().zip(Path::new(path).canonicalize().ok()).is_some_and(|(source,target)|source==target){return Err("Export destination cannot replace the crawl database".into())}let saved=crate::load_project_data(db)?;export_pages(&saved.pages,&saved.seed,path,options)}
#[cfg(test)]mod tests{
 use super::*;use std::io::Read;
 #[test]fn rejected_temporary_collision_never_deletes_another_file(){let dir=directory();let existing=dir.join("occupied.tmp");std::fs::write(&existing,b"other export owns this").unwrap();assert!(own_temporary(existing.clone()).is_err());assert_eq!(std::fs::read(existing).unwrap(),b"other export owns this");std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn simultaneous_packages_in_one_directory_keep_separate_complete_outputs(){let dir=directory();let barrier=std::sync::Arc::new(std::sync::Barrier::new(2));let workers:Vec<_>=(0..2).map(|index|{let out=dir.join(format!("parallel-{index}.zip"));let barrier=barrier.clone();std::thread::spawn(move||{barrier.wait();export_pages(&[page(&format!("https://e.test/שלום-{index}"))],"https://e.test/",out.to_str().unwrap(),options()).unwrap();let mut archive=zip::ZipArchive::new(std::fs::File::open(out).unwrap()).unwrap();assert!(xml(&mut archive,"sitemap-00001.xml").contains(&format!("שלום-{index}")));})}).collect();for worker in workers{worker.join().unwrap();}assert_eq!(std::fs::read_dir(&dir).unwrap().count(),2);std::fs::remove_dir_all(dir).unwrap();}
 fn directory()->PathBuf{let path=std::env::temp_dir().join(format!("fitig-sitemap-package-{}-{}-{}",std::process::id(),std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos(),TEMPORARY_COUNTER.fetch_add(1,std::sync::atomic::Ordering::SeqCst)));std::fs::create_dir(&path).unwrap();path}
 fn page(url:&str)->Page{Page{url:url.into(),status:200,content_type:"text/html".into(),..Default::default()}}
 fn options()->Options{Options{public_base:"https://e.test/".into(),..Default::default()}}
 fn xml(archive:&mut zip::ZipArchive<std::fs::File>,name:&str)->String{let mut bytes=Vec::new();archive.by_name(name).unwrap().read_to_end(&mut bytes).unwrap();if name.ends_with(".gz"){let mut out=String::new();flate2::read::GzDecoder::new(bytes.as_slice()).read_to_string(&mut out).unwrap();out}else{String::from_utf8(bytes).unwrap()}}
 #[test]fn splits_fifty_thousand_and_one_locations_into_a_valid_index(){let dir=directory();let out=dir.join("large.zip");let pages:Vec<_>=(0..50001).map(|i|page(&format!("https://e.test/p{i}"))).collect();let report=export_pages(&pages,"https://e.test/",out.to_str().unwrap(),options()).unwrap();assert_eq!(report.summary.parts.iter().map(|part|part.urls).collect::<Vec<_>>(),vec![50000,1]);let mut archive=zip::ZipArchive::new(std::fs::File::open(out).unwrap()).unwrap();let index=xml(&mut archive,"sitemap-index.xml");assert_eq!(crate::sitemaps::parse(&index).unwrap().1.len(),2);assert_eq!(crate::sitemaps::parse(&xml(&mut archive,"sitemap-00001.xml")).unwrap().1.len(),50000);assert!(xml(&mut archive,"sitemap-00002.xml").contains("/p50000"));std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn gzip_preserves_readable_hebrew_escaping_and_observed_hints(){let dir=directory();let out=dir.join("שלום.zip");let mut p=page("https://e.test/%D7%A9%D7%9C%D7%95%D7%9D?a=1&b=2");p.headers.insert("last-modified".into(),"Sun, 06 Nov 1994 08:49:37 GMT".into());let report=export_pages(&[p],"https://e.test/",out.to_str().unwrap(),Options{gzip:true,lastmod:true,priority:Some(0.8),changefreq:Some("weekly".into()),..options()}).unwrap();assert_eq!(report.summary.lastmod_omitted,0);let mut archive=zip::ZipArchive::new(std::fs::File::open(out).unwrap()).unwrap();let body=xml(&mut archive,"sitemap-00001.xml.gz");assert!(body.contains("https://e.test/שלום?a=1&amp;b=2"));assert!(body.contains("1994-11-06T08:49:37Z"));assert!(body.contains("<priority>0.8</priority>"));assert!(body.contains("<changefreq>weekly</changefreq>"));std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn byte_partitioning_counts_utf8_and_all_xml_wrapper_bytes(){let dir=directory();let out=dir.join("bytes.zip");let pages:Vec<_>=(0..80).map(|i|page(&format!("https://e.test/{}?i={i}","שלום".repeat(12)))).collect();let report=export_pages(&pages,"https://e.test/",out.to_str().unwrap(),Options{max_bytes:1024,..options()}).unwrap();assert!(report.summary.parts.len()>1);let mut archive=zip::ZipArchive::new(std::fs::File::open(out).unwrap()).unwrap();let mut count=0;for part in &report.summary.parts{let body=xml(&mut archive,&part.name);assert_eq!(body.len(),part.uncompressed_bytes);assert!(body.len()<=1024);count+=crate::sitemaps::parse(&body).unwrap().1.len();}assert_eq!(count,80);std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn exclusions_and_unknown_lastmod_are_reported_without_publishing_excluded_urls(){let dir=directory();let out=dir.join("exclusions.zip");let good=page("https://e.test/good");let pages=vec![good.clone(),Page{directives:"NOINDEX,follow".into(),..page("https://e.test/private")},Page{status:404,..page("https://e.test/missing")},Page{canonical:"https://e.test/good".into(),..page("https://e.test/alias")},Page{content_type:"image/png".into(),..page("https://e.test/picture")},good];let report=export_pages(&pages,"https://e.test/",out.to_str().unwrap(),Options{lastmod:true,..options()}).unwrap();assert_eq!(report.summary.eligible_urls,1);assert_eq!(report.excluded.len(),5);assert_eq!(report.summary.lastmod_omitted,1);let mut archive=zip::ZipArchive::new(std::fs::File::open(out).unwrap()).unwrap();assert!(!xml(&mut archive,"manifest.json").contains("/private"));assert!(!xml(&mut archive,"sitemap-00001.xml").contains("/private"));std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn failure_preserves_existing_output_and_removes_own_temporary_file(){let dir=directory();let out=dir.join("existing.zip");std::fs::write(&out,b"preserve").unwrap();for opts in [Options{public_base:"https://other.test/".into(),..options()},Options{max_urls:0,..options()},Options{priority:Some(2.0),..options()}]{assert!(export_pages(&[page("https://e.test/")],"https://e.test/",out.to_str().unwrap(),opts).is_err());assert_eq!(std::fs::read(&out).unwrap(),b"preserve");}let long=page(&format!("https://e.test/{}","a".repeat(1500)));assert!(export_pages(&[long],"https://e.test/",out.to_str().unwrap(),Options{max_bytes:1024,..options()}).is_err());assert_eq!(std::fs::read(&out).unwrap(),b"preserve");assert_eq!(std::fs::read_dir(&dir).unwrap().count(),1);std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn directory_and_encoding_options_preserve_unicode_and_url_identity(){let dir=directory();let out=dir.join("directory.zip");let p=page("https://e.test/%d7%9e%d7%a4%d7%95%d7%aa/item");let report=export_pages(&[p.clone()],"https://e.test/",out.to_str().unwrap(),Options{public_base:"https://e.test/מפות".into(),..options()}).unwrap();assert_eq!(report.summary.outside_public_directory,0);let mut archive=zip::ZipArchive::new(std::fs::File::open(&out).unwrap()).unwrap();assert!(xml(&mut archive,"sitemap-index.xml").contains("https://e.test/מפות/sitemap-00001.xml"));drop(archive);export_pages(&[p],"https://e.test/",out.to_str().unwrap(),Options{readable_unicode:false,..options()}).unwrap();let mut archive=zip::ZipArchive::new(std::fs::File::open(&out).unwrap()).unwrap();assert!(xml(&mut archive,"sitemap-00001.xml").contains("%d7%9e"));drop(archive);std::fs::remove_dir_all(dir).unwrap();}
 #[test]fn package_export_cannot_replace_a_database_even_when_it_has_a_zip_extension(){let dir=directory();let db=dir.join("crawl.zip");{let c=crate::open(db.to_str().unwrap()).unwrap();c.execute("INSERT INTO metadata VALUES('seed','https://e.test/')",[]).unwrap();let p=page("https://e.test/");c.execute("INSERT INTO pages VALUES(?1,?2)",rusqlite::params![p.url,serde_json::to_string(&p).unwrap()]).unwrap();}let before=std::fs::read(&db).unwrap();assert!(export(db.to_str().unwrap(),db.to_str().unwrap(),options()).unwrap_err().to_string().contains("cannot replace"));assert!(std::fs::read(&db).unwrap()==before);std::fs::remove_dir_all(dir).unwrap();}

}
